// products/orders "store" collection ના 2 documents તરીકે save થાય છે
async function storageGet(key) {
  const snap = await getDoc(doc(db, "store", key));
  return snap.exists() ? { value: JSON.stringify(snap.data().value) } : null;
}
async function storageSet(key, value) {
  await setDoc(doc(db, "store", key), { value: JSON.parse(value) });
  return true;
}

